presets.glsl:
vec4 effect(Fx f) {
    float y = sin(f.t * 4.0 - f.o.x * 0.33) * 1.75;
    vec2 src = f.p + vec2(0.0, y);
    return inkShadow(vec3(0.50, 0.91, 1.0), G(src), G(src - 1.0));
}

vec4 effect(Fx f) {
    float ph = fract(f.t * 0.7 - f.o.x * 0.018);
    float hop = ph < 0.2 ? sin(ph / 0.2 * PI) : 0.0;
    vec2 src = f.p + vec2(0.0, floor(hop * 4.0 + 0.5));
    vec3 c = mix(vec3(0.56, 1.0, 0.36), vec3(0.88, 1.0, 0.66), hop);
    // The shadow stays on the ground while the letter is in the air.
    return over(vec4(c, G(src)), vec4(vec3(0.14, 0.25, 0.09), G(f.p - 1.0) * (1.0 - hop * 0.5)));
}

vec4 effect(Fx f) {
    float k = floor(f.t * 16.0);
    vec2 j = vec2(h3(vec3(f.o, k)), h3(vec3(f.o + 17.0, k))) - 0.5;
    vec2 src = f.p - floor(j * 2.6 + 0.5);
    vec3 c = mix(vec3(1.0, 0.33, 0.33), vec3(1.0, 0.68, 0.5), step(0.86, h3(vec3(f.o, k + 3.0))));
    return inkShadow(c, G(src), G(src - 1.0));
}

vec4 effect(Fx f) {
    float k = sin(f.t * 6.0 - f.o.x * 0.4) * 0.22;
    vec2 sc = vec2(1.0 + k, 1.0 - k);
    vec2 c = vec2(f.w * 0.5, f.size.y);
    vec2 src = c + (f.p - c) / sc;
    vec2 ssrc = c + (f.p - 1.0 - c) / sc;
    vec3 col = G(src - vec2(0.0, 1.0)) < 0.5 ? vec3(1.0, 0.82, 0.94) : vec3(1.0, 0.45, 0.78);
    return inkShadow(col, G(src), G(ssrc));
}

vec4 effect(Fx f) {
    // A full turn that rolls through the word, then a rest, so it stays readable.
    float ph = fract(f.t * 0.45 - f.o.x * 0.012);
    float a = ph < 0.3 ? smoothstep(0.0, 1.0, ph / 0.3) * 2.0 * PI : 0.0;
    vec2 c = vec2(f.w * 0.5, 4.0);
    mat2 r = mat2(cos(a), -sin(a), sin(a), cos(a));
    vec2 src = c + r * (f.p - c);
    vec2 ssrc = c + r * (f.p - 1.0 - c);
    return inkShadow(vec3(1.0, 0.86, 0.45), G(src), G(ssrc));
}

vec4 effect(Fx f) {
    float ph = fract(f.t * 0.5 - f.o.x * 0.012);
    float cs = cos(ph < 0.35 ? ph / 0.35 * 2.0 * PI : 0.0);
    float sx = max(abs(cs), 0.06);
    float cx = f.w * 0.5;
    float dx = (f.p.x - cx) / sx;
    float sdx = (f.p.x - 1.0 - cx) / sx;
    vec2 src = vec2(cx + (cs < 0.0 ? -dx : dx), f.p.y);
    vec2 ssrc = vec2(cx + (cs < 0.0 ? -sdx : sdx), f.p.y - 1.0);
    vec3 gold = mix(vec3(1.0, 0.94, 0.56), vec3(0.86, 0.55, 0.12), f.q.y / f.size.y);
    gold *= cs < 0.0 ? 0.62 : 1.0;
    gold = min(gold + (1.0 - sx) * 0.4, 1.0);
    return inkShadow(gold, G(src), G(ssrc));
}

vec4 effect(Fx f) {
    float b = fract(f.t * 1.15);
    float beat = exp(-pow((b - 0.06) * 18.0, 2.0)) + 0.65 * exp(-pow((b - 0.24) * 18.0, 2.0));
    float sc = 1.0 + beat * 0.3;
    vec2 c = vec2(f.w * 0.5, 4.0);
    vec2 src = c + (f.p - c) / sc;
    vec2 ssrc = c + (f.p - 1.0 - c) / sc;
    vec3 col = mix(vec3(0.86, 0.2, 0.32), vec3(1.0, 0.64, 0.72), beat);
    return inkShadow(col, G(src), G(ssrc));
}

vec4 effect(Fx f) {
    // The head sweeps the screen left to right (640 texels covers a title on
    // a wide screen), typing every letter it passes.
    float speed = 55.0;
    float head = mod(f.t * speed, 640.0);
    float age = (head - f.o.x) / speed;
    if (age < 0.0) return vec4(0.0);
    float pop = exp(-age * 7.0);
    vec2 c = vec2(f.w * 0.5, 7.0);
    float sc = 1.0 + 0.7 * pop;
    vec2 src = c + (f.p - c) / sc;
    vec3 col = mix(vec3(0.93, 0.93, 0.88), vec3(1.0, 1.0, 0.55), pop);
    vec4 o = inkShadow(col, G(src), G(c + (f.p - 1.0 - c) / sc));
    // The caret sits after the newest letter.
    if (age < 6.0 / speed && fract(f.t * 2.5) < 0.6
        && f.q.y > 7.0 && f.q.y < 8.0 && f.q.x > f.w + 1.0 && f.q.x < f.w + 6.0) {
        o = over(vec4(1.0, 1.0, 0.7, 1.0), o);
    }
    return o;
}

vec2 ghostAt(float t, float x) {
    return vec2(sin(t * 2.4 + x * 0.12) * 2.5, cos(t * 1.9 + x * 0.1) * 1.2);
}
vec4 effect(Fx f) {
    vec4 col = vec4(0.0);
    for (int i = 3; i >= 1; i--) {
        float a = G(f.p - ghostAt(f.t - float(i) * 0.09, f.o.x)) * (0.42 - float(i) * 0.1);
        col = over(vec4(0.55, 0.85, 1.0, a), col);
    }
    return over(vec4(0.9, 1.0, 1.0, G(f.p - ghostAt(f.t, f.o.x)) * 0.92), col);
}

float flagY(float x, float t) { return sin(x * 0.28 - t * 6.0) * 1.2; }
vec4 effect(Fx f) {
    float x = f.o.x + f.q.x;
    vec2 src = vec2(f.p.x, f.p.y + flagY(x, f.t));
    vec2 ssrc = vec2(f.p.x - 1.0, f.p.y - 1.0 + flagY(x - 1.0, f.t));
    float shade = 0.82 + 0.28 * cos(x * 0.28 - f.t * 6.0);
    return inkShadow(min(vec3(1.0, 0.34, 0.3) * shade, 1.0), G(src), G(ssrc));
}

vec4 effect(Fx f) {
    vec3 c = hsv(fract(floor(f.g.x) * 0.02 - f.t * 0.35), 0.62, 1.0);
    return inkShadow(c, G(f.p), G(f.p - 1.0));
}

vec3 grad3(float s, vec3 a, vec3 b, vec3 c) {
    s = fract(s) * 3.0;
    return s < 1.0 ? mix(a, b, s) : s < 2.0 ? mix(b, c, s - 1.0) : mix(c, a, s - 2.0);
}
vec4 effect(Fx f) {
    vec3 c = grad3(floor(f.g.x) * 0.011 - f.t * 0.12,
                   vec3(1.0, 0.56, 0.22), vec3(1.0, 0.27, 0.56), vec3(0.62, 0.32, 1.0));
    c = mix(c, vec3(1.0), (1.0 - f.q.y / f.size.y) * 0.2);
    return inkShadow(c, G(f.p), G(f.p - 1.0));
}

vec4 effect(Fx f) {
    vec2 g = floor(f.g);
    float s1 = fract((g.x - g.y * 0.6) * 0.045 - f.t * 0.55);
    float s2 = fract((g.x + g.y * 0.4) * 0.03 + f.t * 0.32);
    float glint = smoothstep(0.0, 0.08, s1) * (1.0 - smoothstep(0.08, 0.2, s1))
                + 0.6 * smoothstep(0.0, 0.05, s2) * (1.0 - smoothstep(0.05, 0.14, s2));
    vec3 c = mix(vec3(0.84, 0.5, 1.0), vec3(1.0, 0.94, 1.0), clamp(glint, 0.0, 1.0));
    return inkShadow(c, G(f.p), G(f.p - 1.0));
}

vec4 effect(Fx f) {
    vec2 g = floor(f.g);
    float k = floor(f.t * 6.0);
    float jump = step(0.92, h1(k)) * (h1(k + 3.0) > 0.5 ? 1.0 : -1.0);
    vec2 src = f.p - vec2(jump, 0.0);
    float a = G(src);
    vec3 c = mix(hsv(fract(g.y * 0.05 + g.x * 0.012 + f.t * 0.3), 0.35, 1.0), vec3(0.5, 1.0, 1.0), 0.35);
    float scan = mod(g.y + floor(f.t * 10.0), 3.0) < 1.0 ? 0.55 : 1.0;
    vec4 col = vec4(c, a * (0.78 + 0.15 * sin(f.t * 40.0)) * scan);
    col = over(col, vec4(1.0, 0.3, 0.6, max(G(src - vec2(1.0, 0.0)) - a, 0.0) * 0.55));
    col = over(col, vec4(0.2, 0.9, 1.0, max(G(src + vec2(1.0, 0.0)) - a, 0.0) * 0.55));
    return over(col, vec4(0.4, 1.0, 1.0, N8(src) * (1.0 - a) * 0.18));
}

vec4 effect(Fx f) {
    float hid = h2(f.o);
    float ph = fract(f.t * 1.4 + hid);
    float hop = ph < 0.3 ? sin(ph / 0.3 * PI) : 0.0;
    vec2 src = f.p + vec2(0.0, floor(hop * 3.0 + 0.5));
    vec4 col = inkShadow(hsv(fract(hid + f.t * 0.5), 0.7, 1.0), G(src), G(f.p - 1.0));
    vec2 fall = vec2(f.g.x + floor(sin(f.t * 2.0 + floor(f.g.x / 3.0)) * 1.0), f.g.y - f.t * 9.0);
    vec2 cell = floor(fall / 3.0);
    if (h2(cell) > 0.88 && floor(mod(fall.x, 3.0)) == 1.0 && floor(mod(fall.y, 3.0)) == 1.0 && f.p.y < 2.0) {
        float fade = clamp((f.p.y + 6.0) / 3.0, 0.0, 1.0);
        col = over(col, vec4(hsv(h2(cell + 1.7), 0.75, 1.0), fade));
    }
    return col;
}

vec4 effect(Fx f) {
    float a = G(f.p);
    float row = f.q.y / f.size.y;
    vec3 c = row < 0.25 ? vec3(1.0, 0.96, 0.66)
           : row < 0.5 ? vec3(1.0, 0.85, 0.29)
           : row < 0.75 ? vec3(0.94, 0.66, 0.12)
           : vec3(0.72, 0.43, 0.06);
    vec2 g = floor(f.g);
    float band = mod(g.x + g.y * 0.7 - f.t * 70.0, 160.0);
    c = mix(c, vec3(1.0), band < 3.0 ? 0.85 : 0.0);
    vec4 col = over(vec4(c, a), vec4(0.23, 0.13, 0.0, N4(f.p) * (1.0 - a)));
    float clock = f.t * 1.3 + h2(f.o) * 5.0;
    float k = floor(clock);
    if (h3(vec3(f.o, k)) > 0.7) {
        vec2 sp = vec2(floor(h3(vec3(f.o, k + 1.0)) * max(f.w, 1.0)), floor(h3(vec3(f.o, k + 2.0)) * 6.0)) + 0.5;
        float sz = floor(sin(fract(clock) * PI) * 2.5);
        vec2 d = abs(f.q - sp);
        if ((d.x < 0.5 && d.y <= sz) || (d.y < 0.5 && d.x <= sz)) col = over(vec4(1.0, 1.0, 0.92, 1.0), col);
    }
    return col;
}

vec4 effect(Fx f) {
    vec2 q = f.q;
    float heat = 0.0;
    for (int k = 1; k <= 7; k++) {
        float fk = float(k);
        float wob = floor((vnoise(vec2((f.o.x + q.x) * 0.5, (q.y + fk) * 0.4 + f.t * 6.0)) - 0.5) * 2.6 + 0.5);
        heat = max(heat, G(vec2(q.x + wob, q.y + fk)) * (1.0 - fk / 8.0));
    }
    heat *= 0.45 + 0.75 * vnoise(vec2(floor(f.g.x) * 0.55, floor(f.g.y) * 0.5 + f.t * 8.0));
    float lv = floor(heat * 5.0);
    vec4 fire = lv >= 4.0 ? vec4(1.0, 0.97, 0.7, 1.0)
              : lv >= 3.0 ? vec4(1.0, 0.82, 0.24, 1.0)
              : lv >= 2.0 ? vec4(1.0, 0.52, 0.12, 1.0)
              : lv >= 1.0 ? vec4(0.82, 0.2, 0.08, 0.95)
              : heat > 0.08 ? vec4(0.25, 0.1, 0.08, 0.55) : vec4(0.0);
    float a = G(f.p);
    float fl = vnoise(vec2(floor(f.g.x) * 0.7, floor(f.g.y) * 0.7 + f.t * 5.0));
    vec3 body = mix(vec3(1.0, 0.98, 0.72), vec3(1.0, 0.62, 0.16), f.q.y / f.size.y);
    body = mix(body, vec3(1.0), step(0.72, fl) * 0.6);
    // A dark rim round the letter is what keeps it readable through its own flames.
    vec4 rim = vec4(0.24, 0.04, 0.0, N8(f.p) * (1.0 - a));
    return over(vec4(body, a), over(rim, fire));
}

vec4 effect(Fx f) {
    vec2 g = floor(f.g);
    float n = fbm(vec2(g.x * 0.22, g.y * 0.22 - f.t * 0.7));
    float n2 = vnoise(vec2(g.x * 0.5 + f.t * 0.3, g.y * 0.5 - f.t * 1.4));
    vec3 c = mix(vec3(1.0, 0.36, 0.04), vec3(1.0, 0.86, 0.3), smoothstep(0.3, 0.7, n2));
    c = mix(c, vec3(0.32, 0.12, 0.07), smoothstep(0.6, 0.64, n));
    c = mix(c, vec3(1.0, 0.97, 0.7), 1.0 - smoothstep(0.0, 0.025, abs(n - 0.57)));
    float a = G(f.p);
    float glow = (1.0 - a) * (0.3 + 0.12 * sin(f.t * 5.0 + g.x));
    vec4 col = over(vec4(c, a), vec4(0.16, 0.03, 0.0, N4(f.p) * (1.0 - a)));
    return over(col, vec4(1.0, 0.45, 0.05, glow * (N8(f.p) - N4(f.p) + exp(-inkDist(f.p) * 1.2))));
}

vec4 effect(Fx f) {
    float a = G(f.p);
    vec2 g = floor(f.g);
    vec3 c = mix(vec3(0.9, 0.98, 1.0), vec3(0.45, 0.75, 0.95), f.q.y / f.size.y);
    c *= 0.9 + 0.2 * h2(g);
    c = mix(c, vec3(1.0), a * (1.0 - G(f.p - vec2(0.0, 1.0))));
    vec4 col = vec4(min(c, 1.0), a);
    float hc = h2(vec2(g.x, 3.7));
    float up1 = G(f.p - vec2(0.0, 1.0));
    float up2 = G(f.p - vec2(0.0, 2.0));
    float ice = (1.0 - a) * (up1 * step(0.5, hc) * 0.85 + (1.0 - up1) * up2 * step(0.8, hc) * 0.6);
    col = over(col, vec4(0.75, 0.92, 1.0, ice));
    col = over(col, vec4(0.08, 0.2, 0.36, N4(f.p) * (1.0 - a) * (1.0 - ice) * 0.75));
    float clock = f.t * 0.9 + h2(f.o) * 7.0;
    float k = floor(clock);
    if (h3(vec3(f.o, k)) > 0.6) {
        vec2 sp = vec2(floor(h3(vec3(f.o, k + 1.0)) * max(f.w, 1.0)), floor(h3(vec3(f.o, k + 2.0)) * 7.0)) + 0.5;
        float sz = floor(sin(fract(clock) * PI) * 2.0);
        vec2 d = abs(f.q - sp);
        if ((d.x < 0.5 && d.y <= sz) || (d.y < 0.5 && d.x <= sz)) col = over(vec4(1.0), col);
    }
    return col;
}

// A letter as a tank: the liquid's surface, in glyph texels from the top.
float tankSurface(Fx f, float level, float speed) {
    float x = f.o.x + f.q.x;
    return f.size.y * (1.0 - level)
         + sin(x * 0.55 - f.t * speed) * 0.7
         + sin(x * 0.23 + f.t * speed * 0.6) * 0.5;
}
vec4 effect(Fx f) {
    float a = G(f.p);
    float surf = tankSurface(f, 0.56 + 0.06 * sin(f.t * 0.9), 3.2);
    float depth = f.q.y - surf;
    vec3 c;
    if (depth < 0.0) {
        c = G(f.p - vec2(0.0, 1.0)) < 0.5 ? vec3(0.44, 0.47, 0.56) : vec3(0.27, 0.29, 0.37);
    } else {
        c = mix(vec3(0.16, 0.5, 0.98), vec3(0.06, 0.24, 0.72), clamp(depth / 5.0, 0.0, 1.0));
        if (depth < 1.0) c = vec3(0.42, 0.74, 1.0);
        // Caustics: light that wanders through the water.
        float k = vnoise(vec2((f.o.x + f.q.x) * 0.5 + f.t * 0.8, f.q.y * 0.7 - f.t * 0.5));
        if (depth >= 1.0 && k > 0.72) c = mix(c, vec3(0.5, 0.8, 1.0), 0.45);
        if (depth >= 1.0 && h3(vec3(floor(f.g.x), floor(f.g.y + f.t * 3.0), 2.0)) > 0.95) c = vec3(0.75, 0.9, 1.0);
    }
    return over(vec4(c, a), vec4(0.03, 0.04, 0.08, G(f.p - 1.0) * 0.85));
}

float lavaSurface(Fx f) {
    float x = f.o.x + f.q.x;
    return f.size.y * (1.0 - 0.52 - 0.05 * sin(f.t * 0.6))
         + sin(x * 0.4 - f.t * 1.3) * 0.6
         + sin(x * 0.17 + f.t * 0.8) * 0.5;
}
vec4 effect(Fx f) {
    float a = G(f.p);
    float surf = lavaSurface(f);
    float depth = f.q.y - surf;
    vec2 g = floor(f.g);
    vec3 c;
    if (depth < 0.0) {
        // Basalt above the lava, warmed from below.
        c = G(f.p - vec2(0.0, 1.0)) < 0.5 ? vec3(0.4, 0.36, 0.35) : vec3(0.24, 0.21, 0.21);
        c = mix(c, vec3(0.55, 0.2, 0.08), clamp(1.0 + depth / 2.0, 0.0, 1.0));
    } else {
        float n = vnoise(vec2(g.x * 0.35 + f.t * 0.4, g.y * 0.5 - f.t * 0.25));
        c = mix(vec3(1.0, 0.42, 0.04), vec3(0.78, 0.12, 0.02), clamp(depth / 5.0, 0.0, 1.0));
        c = mix(c, vec3(1.0, 0.8, 0.22), smoothstep(0.55, 0.8, n));
        if (n < 0.22) c = mix(c, vec3(0.35, 0.08, 0.03), 0.6);
        if (depth < 1.0) c = vec3(1.0, 0.92, 0.5);
    }
    vec4 col = over(vec4(c, a), vec4(0.06, 0.02, 0.01, G(f.p - 1.0) * 0.85));
    // A bubble swells at the surface and pops, one letter at a time.
    float clock = f.t * 0.8 + h2(f.o) * 9.0;
    float k = floor(clock);
    float life = fract(clock);
    if (h3(vec3(f.o, k)) > 0.45) {
        float bx = floor(h3(vec3(f.o, k + 1.0)) * max(f.w - 1.0, 1.0)) + 0.5;
        float r = life < 0.8 ? life / 0.8 * 1.4 : 0.0;
        float sy = floor(lavaSurface(f)) + 0.5;
        float d = length(vec2(f.q.x - bx, (f.q.y - sy) * 1.3));
        if (r > 0.3 && d < r && f.q.y <= sy) col = over(vec4(1.0, 0.68, 0.16, d > r - 0.8 ? 1.0 : 0.85), col);
        // The pop: two sparks thrown up.
        if (life >= 0.8) {
            float up = (life - 0.8) / 0.2 * 3.0;
            if (abs(f.q.y - (sy - 1.0 - floor(up))) < 0.5 && abs(abs(f.q.x - bx) - 1.0 - floor(up * 0.5)) < 0.5) {
                col = over(vec4(1.0, 0.85, 0.35, 1.0 - (life - 0.8) / 0.2), col);
            }
        }
    }
    return col;
}

vec4 effect(Fx f) {
    float a = G(f.p);
    vec3 c = G(f.p - vec2(0.0, 1.0)) < 0.5 ? vec3(0.74, 1.0, 0.64)
           : G(f.p + vec2(0.0, 1.0)) < 0.5 ? vec3(0.22, 0.6, 0.2) : vec3(0.45, 0.88, 0.38);
    vec4 col = vec4(c, a);
    float bottom = -1.0;
    for (int y = 15; y >= 0; y--) {
        if (float(y) < f.size.y && G(vec2(f.q.x, float(y) + 0.5)) > 0.5) { bottom = float(y); break; }
    }
    float hc = h2(vec2(floor(f.g.x), 9.1));
    if (bottom >= 0.0 && a < 0.5 && hc > 0.5) {
        float life = fract(f.t * 0.3 + hc * 13.0);
        float dy = floor(f.q.y) - bottom;
        float len = life < 0.7 ? floor(smoothstep(0.0, 0.7, life) * 4.0) : floor(4.0 * (1.0 - (life - 0.7) / 0.3));
        if (dy >= 1.0 && dy <= len) col = vec4(0.4, 0.85, 0.34, 0.95);
        if (life > 0.7 && abs(dy - floor(5.0 + (life - 0.7) * 24.0)) < 0.5) {
            col = vec4(0.58, 0.96, 0.52, 0.95 * (1.0 - (life - 0.7) / 0.3));
        }
    }
    return over(col, vec4(0.05, 0.2, 0.05, G(f.p - 1.0) * 0.6));
}

vec4 effect(Fx f) {
    float a = G(f.p);
    vec2 g = floor(f.g);
    float n = fbm(g * 0.12 + vec2(f.t * 0.06, f.t * 0.02));
    float m = vnoise(g * 0.2 - vec2(f.t * 0.1, 0.0));
    vec3 c = mix(vec3(0.3, 0.18, 0.7), vec3(0.62, 0.5, 1.0), smoothstep(0.3, 0.75, n));
    c = mix(c, vec3(1.0, 0.5, 0.85), smoothstep(0.5, 0.85, m) * 0.75);
    float s = h2(g);
    if (s > 0.9) c = mix(c, vec3(1.0), 0.5 + 0.5 * sin(f.t * 3.0 + s * 60.0));
    vec4 col = over(vec4(c, a), vec4(0.04, 0.0, 0.1, N4(f.p) * (1.0 - a)));
    return over(col, vec4(0.62, 0.42, 1.0, exp(-inkDist(f.p) * 0.9) * (1.0 - col.a) * 0.45));
}

vec4 effect(Fx f) {
    vec2 g = floor(f.g);
    float sp = 7.0 + 9.0 * h1(g.x * 1.31);
    float head = mod(f.t * sp + h1(g.x * 7.7) * 40.0, 24.0);
    float dy = mod(head - g.y, 24.0);
    float br = dy < 1.0 ? 1.4 : exp(-dy * 0.28);
    float a = G(f.p);
    vec3 c = br > 1.0 ? vec3(0.85, 1.0, 0.88) : mix(vec3(0.1, 0.42, 0.14), vec3(0.4, 1.0, 0.5), br);
    return over(vec4(c, a), vec4(0.1, 0.9, 0.3, N8(f.p) * (1.0 - a) * 0.22 * min(br, 1.0)));
}

vec4 effect(Fx f) {
    float k = floor(f.t * 9.0);
    float on = step(0.1, h1(k * 0.37 + floor(f.o.y)));
    if (h2(f.o) > 0.8) on *= step(0.45, h1(k * 1.7 + f.o.x));
    float core = G(f.p);
    vec3 tube = vec3(1.0, 0.31, 0.85);
    vec4 col = vec4(tube, exp(-inkDist(f.p) * 1.1) * 0.7 * on * (1.0 - core));
    vec3 cc = on > 0.5 ? mix(vec3(1.0, 0.86, 0.97), tube, 0.25) : tube * 0.35;
    return over(vec4(cc, core), col);
}

vec4 effect(Fx f) {
    float a = G(f.p);
    float inner = min(min(G(f.p + vec2(1.0, 0.0)), G(f.p - vec2(1.0, 0.0))), min(G(f.p + vec2(0.0, 1.0)), G(f.p - vec2(0.0, 1.0))));
    float flash = step(0.88, h1(floor(f.t * 7.0)));
    vec3 c = mix(vec3(0.85, 1.0, 1.0), vec3(0.3, 0.75, 1.0), a * (1.0 - inner));
    vec4 col = vec4(mix(c, vec3(1.0), flash * 0.6), a);
    float d = inkDist(f.p);
    if (a < 0.5 && d < 3.0) {
        float k = floor(f.t * 14.0);
        float n = vnoise(floor(f.g) * 0.55 + vec2(k * 3.7, k * 1.3));
        float line = step(0.5, 1.0 - smoothstep(0.0, 0.06, abs(n - 0.5)));
        col = over(col, vec4(0.75, 0.95, 1.0, line * (1.0 - d / 3.0)));
        col = over(col, vec4(0.3, 0.6, 1.0, exp(-d * 1.5) * (0.35 + flash * 0.3)));
    }
    return col;
}

vec4 effect(Fx f) {
    float ang = 0.785 + sin(f.t * 1.4) * 0.6;
    vec2 dir = vec2(cos(ang), sin(ang));
    float a = G(f.p);
    vec3 face = G(f.p - vec2(0.0, 1.0)) < 0.5 ? vec3(0.78, 1.0, 0.98) : vec3(0.36, 0.89, 0.88);
    vec4 col = vec4(face, a);
    for (int k = 1; k <= 8; k++) {
        if (col.a > 0.5) break;
        if (G(f.p - floor(dir * float(k) * 0.5 + 0.5)) > 0.5) {
            col = vec4(mix(vec3(0.13, 0.62, 0.66), vec3(0.04, 0.24, 0.3), float(k) / 8.0), 1.0);
        }
    }
    return col;
}

vec4 effect(Fx f) {
    float a = G(f.p);
    float edge = (1.0 - a) * N8(f.p);
    // The sticker's own silhouette (letter plus border), offset for the shadow.
    vec2 sp = f.p - vec2(1.0, 2.0);
    float sh = max(G(sp), N8(sp));
    vec2 g = floor(f.g);
    float gloss = mod(g.x - g.y * 0.8 - f.t * 45.0, 110.0) < 4.0 ? 0.55 : 0.0;
    vec3 ink = mix(vec3(1.0, 0.35, 0.6), vec3(1.0, 0.62, 0.78), G(f.p - vec2(0.0, 1.0)) < 0.5 ? 1.0 : 0.0);
    vec4 col = vec4(mix(ink, vec3(1.0), gloss), a);
    col = over(col, vec4(mix(vec3(1.0), vec3(0.85, 0.88, 0.95), step(4.0, f.q.y)), edge));
    return over(col, vec4(0.05, 0.03, 0.08, sh * 0.55));
}

vec4 effect(Fx f) {
    float k = floor(f.t * 14.0);
    float burst = step(0.5, h1(floor(f.t * 2.5) * 1.37));
    float band = floor(f.g.y / 2.0);
    float sh = (h2(vec2(band, k)) - 0.5) * 7.0 * burst * step(0.6, h2(vec2(band * 3.1, k + 1.0)));
    vec2 src = f.p - vec2(floor(sh + 0.5), 0.0);
    float sp = 1.0 + burst;
    float r = G(src + vec2(sp, 0.0));
    float gg = G(src);
    float b = G(src - vec2(sp, 0.0));
    float al = max(max(r, gg), b);
    vec3 c = vec3(max(r, gg * 0.95), gg, max(b, gg));
    if (burst > 0.5 && h3(vec3(floor(f.g), k)) > 0.975) { c = vec3(1.0); al = 1.0; }
    return over(vec4(c, al), vec4(0.0, 0.0, 0.0, G(f.p - 1.0) * 0.6));
}

float dsMoment(vec2 key) { return 0.6 + h2(key) * 1.4; }
float dsBack(vec2 key) { return 3.6 + h2(key + 31.0) * 0.8; }
vec4 effect(Fx f) {
    float u = fract(f.t / 5.0 - f.o.x * 0.002) * 5.0;
    vec2 base = floor(f.o);
    vec2 q = floor(f.p);
    float a = G(f.p);
    float m = dsMoment(base + q);
    float back = dsBack(base + q);
    vec4 col = vec4(0.0);
    if (a > 0.5 && (u < m || u > back)) {
        float hot = u < m ? 1.0 - smoothstep(0.0, 0.3, m - u) : 1.0 - smoothstep(0.0, 0.25, u - back);
        col = vec4(mix(vec3(0.89, 0.8, 1.0), vec3(1.0, 0.55, 1.0), hot), 1.0);
    }
    for (int k = 1; k <= 9; k++) {
        for (int dx = -1; dx <= 1; dx++) {
            vec2 src = q + vec2(float(dx), float(k));
            if (G(src + 0.5) < 0.5) continue;
            float sm = dsMoment(base + src);
            if (u <= sm || u >= dsBack(base + src)) continue;
            float age = u - sm;
            float sway = floor(sin(age * 4.0 + h2(base + src) * 6.0) + 0.5);
            if (floor(age * 5.0) == float(k) && sway == float(-dx)) {
                col = over(col, vec4(mix(vec3(1.0, 0.7, 1.0), vec3(0.42, 0.18, 1.0), age / 1.8), 1.0 - age / 2.0));
            }
        }
    }
    return over(col, vec4(0.1, 0.03, 0.2, G(f.p - 1.0) * (u < m ? 0.8 : 0.0)));
}

vec4 effect(Fx f) {
    float u = fract(f.t / 4.5) * 4.5;
    float at = 0.4 + mod(f.o.x, 160.0) * 0.016;
    if (u > at && u < 3.9) {
        float flash = 1.0 - smoothstep(0.0, 0.25, u - at);
        return inkShadow(mix(vec3(0.85, 1.0, 0.9), vec3(1.0), flash), G(f.p), G(f.p - 1.0));
    }
    // Static: a fresh random pattern fifteen times a second, inside the letter's own box.
    float k = floor(f.t * 15.0);
    bool box = f.q.x < max(f.w, 3.0) && f.q.y > 1.0 && f.q.y < 7.0;
    float on = box && h3(vec3(floor(f.p) + f.o * 1.37, k)) > 0.62 ? 1.0 : 0.0;
    return vec4(0.3, 0.95, 0.5, on * 0.9);
}
